#!/bin/bash
# fact.sh - Shell script to to find factorial of given command line arg
factorial(){ local i=$1 local f declare -i i declare -i f # factorial() is called until the value of $f is returned and is it is <= 2 # This is called the recursion [ $i -le 2 ] && echo $i || { f=$(( $(factorial $((i-1)) ) * i )); echo $f; }
} # display usage
[ $# -eq 0 ] && { echo "Usage: $0 number"; exit 1; } # call factorial
factorial $1

