Tính chất nối chuỗi, tức là then sau sẽ đợi return data từ then trước (nếu nó resolve) Tức là kết quả trả về của function đằng trước là input của function đằng sau let promise = new Promise( function (resolve, reject) { resolve(); }
); promise .then(function () { return 1; }) .then(function (data) { console.log(data); return 2; }) .then(function (data) { console.log(data); return 3; }) .then(function (data) { console.log(data); }) .catch(function () { console.log('Failure!'); }) .finally(function () { console.log('Done!'); }) return promise let promise = new Promise( function (resolve, reject) { resolve(); }
); promise .then(function () { /** * Nếu return ra bất cứ cái gì không phải promise * thì * thằng đằng sau sẽ chạy ngay khi được return * * Nếu return promise * thì * thằng đằng sau phải đợi promise xử lý xong mới được chạy * * Lúc này promise được return, có method .then bên dưới * Tương tự như việc khởi tạo promise và gọi .then như thông thường */ // arrow function (recommend) return new Promise((resolve, reject) => { // setTimeout(reject, 3000); setTimeout(resolve, 3000); }) }) /** * Thằng then này được xem là method của promise được * return ở thằng then trước nó. * * Nó phải đợi promise xử lí logic xong và call resolve thì mới được thực thi * Nếu promise ở trên reject thì nó nhảy đến call catch như thông thường */ .then(function () { console.log('Successfully!'); }) .catch(function () { console.log('Failure!'); }) .finally(function () { console.log('Done!'); }) function sleep(ms) { return new Promise((resolve, reject) => { setTimeout(resolve, ms); });
} sleep(1000) .then(() => { console.log(1); return sleep(1000); }).then(() => { console.log(2); return sleep(1000); }).then(() => { console.log(3); return new Promise((resolve, reject) => { reject(); }); }).then(() => { console.log(4); // skip do reject ở trên nó return sleep(1000); }).catch(() => { console.log("Error"); });

