@TestFactory dùng để tạo test động (Dynamic Test) thay vì test cố định. Tạo test dựa vào giá trị động, phụ thuộc vào runtime, tức là test sẽ không cố định Các phương thức phải trả về Collection hoặc Stream. Collection Là một tập hợp (list, set, v.v.) chứa nhiều DynamicTest. Dùng khi số lượng test đã biết trước và không cần xử lý theo luồng (stream). Stream: Dùng khi số lượng test chưa biết trước (lấy từ API, file, database, v.v.). Dùng .map() để biến đổi dữ liệu thành test động. Test API lấy danh sách user từ server import org.junit.jupiter.api.*;
import org.junit.jupiter.api.DynamicTest;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.List;
import java.util.stream.Stream;
import static org.junit.jupiter.api.Assertions.*; class ApiTest { // Giả sử đây là API call thực tế (thay bằng logic thực tế của bạn) List<String> getUsersFromApi() { return List.of("alice", "bob", "charlie"); // Dữ liệu có thể thay đổi mỗi lần chạy } @TestFactory Stream<DynamicTest> testUserApi() { List<String> users = getUsersFromApi(); return users.stream() .map(user -> DynamicTest.dynamicTest("Kiểm tra user: " + user, () -> assertTrue(user.length() > 2, "User quá ngắn: " + user))); }
} Test với dữ liệu từ Database import org.junit.jupiter.api.*;
import org.junit.jupiter.api.DynamicTest;
import java.util.List;
import java.util.stream.Stream;
import static org.junit.jupiter.api.Assertions.*; class DatabaseTest { // Giả sử đây là phương thức lấy dữ liệu từ DB (thay bằng truy vấn thực tế) List<String> getUsernamesFromDatabase() { return List.of("admin", "guest", "root"); // Dữ liệu có thể thay đổi mỗi lần test } @TestFactory Stream<DynamicTest> validateDatabaseUsers() { List<String> usernames = getUsernamesFromDatabase(); return usernames.stream() .map(username -> DynamicTest.dynamicTest("Kiểm tra username: " + username, () -> assertFalse(username.isEmpty(), "Username không được rỗng"))); }
}

