Thuật toán này chọn một phần tử làm pivot, phân chia mảng thành hai phần dựa trên pivot, sau đó sắp xếp từng phần một cách đệ quy. Đây cũng là một thuật toán chia để trị. for each (unsorted) partition set first element as pivot storeIndex = pivotIndex+1 for i = pivotIndex+1 to rightmostIndex if ((a[i] < a[pivot]) or (equal but 50% lucky)) swap(i, storeIndex); ++storeIndex swap(pivot, storeIndex-1) function QuickSort(array &$arr, int $left, int $right): void
{ if ($left < $right) { $pivotIndex = partition($arr, $left, $right); QuickSort($arr, $left, $pivotIndex - 1); QuickSort($arr, $pivotIndex + 1, $right); }
} function partition(array &$arr, int $left, int $right): int
{ $pivot = $arr[$left]; $storeIndex = $left + 1; for ($i = $left + 1; $i <= $right; $i++) { if ($arr[$i] < $pivot || ($arr[$i] == $pivot && rand(0, 1) == 1)) { [$arr[$i], $arr[$storeIndex]] = [$arr[$storeIndex], $arr[$i]]; $storeIndex++; } } [$arr[$left], $arr[$storeIndex - 1]] = [$arr[$storeIndex - 1], $arr[$left]]; return $storeIndex - 1;
}

