Linked List (Danh sách liên kết) là một cấu trúc dữ liệu bao gồm một chuỗi các node (nút), trong đó mỗi node chứa hai thành phần chính: Dữ liệu : Giá trị mà node lưu trữ. Con trỏ : Trỏ đến node tiếp theo trong danh sách. Không giống như mảng, các phần tử của linked list không nằm liên tiếp trong bộ nhớ. Điều này làm cho linked list linh hoạt hơn trong việc thêm hoặc xoá các phần tử, vì không cần di chuyển các phần tử khác để giữ thứ tự. Các loại Linked List : Singly Linked List: Mỗi node chứa dữ liệu và một con trỏ trỏ đến node kế tiếp. Không có con trỏ quay lại node trước đó. Doubly Linked List: Mỗi node chứa dữ liệu và hai con trỏ: một trỏ đến node kế tiếp và một trỏ đến node trước đó. Circular Linked List: Một biến thể của Singly hoặc Doubly Linked List, trong đó node cuối cùng trỏ lại node đầu tiên, tạo thành một vòng lặp. Các thao tác cơ bản trên Linked List : Thêm phần tử (Insertion) Xoá phần tử (Deletion): Tìm kiếm (Search) Duyệt danh sách (Traversal) class Node
{ public $data; public $next; public function __construct($data) { $this->data = $data; $this->next = null; }
} class LinkedList
{ private $head; private $tail; public function __construct() { $this->head = null; $this->tail = null; } public function insertAtBeginning($data) { $newnode = new Node($data); if ($this->head === null) { $this->head = $newnode; $this->tail = $newnode; } else { $newnode->next = $this->head; $this->head = $newnode; } } public function insertAtEnd($data) { $newNode = new Node($data); if ($this->head === null) { $this->head = $newNode; $this->tail = $newNode; } else { $this->tail->next = $newNode; $this->tail = $newNode; } } public function display() { $current = $this->head; while ($current !== null) { echo $current->data . " "; $current = $current->next; } echo "<br>"; //PHP_EOL; // \n, \r\n } public function deleteFirst() { if ($this->head !== null) { $this->head = $this->head->next; if ($this->head === null) { $this->tail = null; } } } public function deleteLast() { if ($this->head === null) { return; } if ($this->head->next === null) { $this->head = null; $this->tail = null; } $current = $this->head; while ($current->next !== $this->tail) { $current = $current->next; } $current->next = null; $this->tail = $current; }
} $linkedList = new LinkedList();
$linkedList->insertAtEnd(1);
$linkedList->insertAtEnd(2);
