class Queue { private $queue = []; // Thêm phần tử vào cuối hàng đợi public function enqueue($item) { array_push($this->queue, $item); } // Lấy phần tử từ đầu hàng đợi public function dequeue() { if (!$this->isEmpty()) { return array_shift($this->queue); } else { return null; } } // Xem phần tử đầu tiên trong hàng đợi public function peek() { return reset($this->queue); } public function isEmpty() { return empty($this->queue); }
} // Sử dụng queue
$myQueue = new Queue();
$myQueue->enqueue(1);
$myQueue->enqueue(2);
$myQueue->enqueue(3);
echo $myQueue->dequeue(); echo $myQueue->peek(); array_push($array, $item) : Thêm một phần tử vào cuối mảng, hoạt động như push trong Stack và enqueue trong Queue. array_pop($array) : Lấy và xóa phần tử cuối cùng của mảng, hoạt động như pop trong Stack. array_shift($array) : Lấy và xóa phần tử đầu tiên của mảng, hoạt động như dequeue trong Queue. end($array) : Lấy phần tử cuối cùng của mảng mà không xóa nó, hoạt động như peek trong Stack. reset($array) : Lấy phần tử đầu tiên của mảng mà không xóa nó, hoạt động như peek (hoặc front) trong Queue. empty($array) : Kiểm tra mảng có rỗng không, dùng để xác định trạng thái của Stack hoặc Queue.

