Trong trường hợp này ta có 2 bảng products và flavors tương ứng với model Product và Flavor . 2 model này có mối quan hệ N-N với nhau: // product model
public function flavors()
{ return $this->belongsToMany(Flavor::class, 'product_flavors') ->withPivot('quantity');
} // flavor model
public function products()
{ return $this->belongsToMany(Product::class, 'product_flavors') ->withPivot('quantity');
} Trong đó bảng product_flavors (model ProductFlavor ) là bảng trung gian (pivot table) chứa các cột product_id và flavor_id , và các cột bổ sung thêm như là quantity Các phương thức dùng pivot: public function storeProductFlavor(Product $product, $flavorId, $quantity)
{ // Thêm flavor mới cùng với quantity vào pivot table $product->flavors()->attach($flavorId, ['quantity' => $quantity]);
} public function deleteProductFlavor(Product $product, $flavorId)
{ // $product->flavors()->where('flavor_id', $flavorId)->delete(); // Xóa flavor khỏi pivot table $product->flavors()->detach($flavorId);
} public function updateProductFlavorQuantity(Product $product, $flavorId, $quantity)
{ // Cập nhật quantity của flavor hiện tại trong pivot table $product->flavors()->updateExistingPivot($flavorId, ['quantity' => $quantity]);
} public function deleteFlavorByProduct(Product $product)
{ // $product->flavors()->delete(); // ProductFlavor::where('product_id', $product->id)->delete(); $product->flavors()->detach(); // pivot
} Cú pháp của attach: $model->relation()->attach($id, ['additional_columns' => 'value']); Ở đây, $id là giá trị của khóa ngoại (foreign key), và mảng thứ hai chứa các cột bổ sung cùng giá trị của chúng.

