public function getFlavorsWithCheckedStatus(Product $product)
{ // Lấy tất cả các flavors $allFlavors = Flavor::all(); // Lấy các id của flavors của sản phẩm $productFlavorIds = $product->flavors()->pluck('flavor_id')->toArray(); // Lấy các mối quan hệ flavors của sản phẩm cùng với quantity $productFlavors = $product->flavors()->get(['flavor_id', 'quantity'])->keyBy('flavor_id'); // Ánh xạ các flavors và thêm thông tin quantity $flavorsWithCheckedStatus = $allFlavors->map(function ($flavor) use ($productFlavorIds, $productFlavors) { return [ 'id' => $flavor->id, 'name' => $flavor->name, 'is_checked' => in_array($flavor->id, $productFlavorIds), 'quantity' => $productFlavors->has($flavor->id) ? $productFlavors->get($flavor->id)->quantity : 0, ]; }); return $flavorsWithCheckedStatus;
} $allFlavors->map(...) : map được gọi trên $allFlavors , là một collection chứa tất cả các bản ghi từ bảng flavors. map sẽ lặp qua từng phần tử trong $allFlavors (mỗi phần tử là một đối tượng Flavor). Hàm callback : Hàm callback được truyền vào map có một tham số $flavor đại diện cho từng phần tử trong $allFlavors . use ( $productFlavorIds , $productFlavors ) là cú pháp để sử dụng các biến bên ngoài hàm callback trong hàm callback. Lặp qua từng phần tử ($flavor) : Đối với mỗi flavor, hàm callback sẽ tạo ra một mảng kết hợp với các thông tin: id : ID của flavor. name : Tên của flavor. is_checked : Kiểm tra xem ID của flavor có nằm trong mảng $productFlavorIds hay không. Nếu có, giá trị là true, ngược lại là false. quantity : Kiểm tra xem flavor có tồn tại trong mảng $productFlavors không. Nếu có, lấy giá trị quantity tương ứng, nếu không, gán giá trị là 0. Cụ thể: // $allFlavors:
[ (object) ['id' => 1, 'name' => 'Flavor X'], (object) ['id' => 2, 'name' => 'Flavor Y'], (object) ['id' => 3, 'name' => 'Flavor Z'],
] // ------------------------------------------------ // $productFlavorIds:
[1, 2] // ------------------------------------------------ // $productFlavors:
[ 1 => (object) ['flavor_id' => 1, 'quantity' => 10], 2 => (object) ['flavor_id' => 2, 'quantity' => 5],
] // ------------------------------------------------

