public function updateProductFlavors(Product $product, $newFlavors, $quantity)
{ $currentFlavorIds = $this->getFlavorIDByProduct($product); $newFlavorIds = array_map('intval', $newFlavors); // Chuyển các ID thành integer // flavors cần thêm mới $flavorsToAdd = array_diff($newFlavorIds, $currentFlavorIds); // flavors cần xóa $flavorsToRemove = array_diff($currentFlavorIds, $newFlavorIds); // Cập nhật flavors mới foreach ($flavorsToAdd as $flavorId) { $this->storeProductFlavor($product, $flavorId, $quantity[$flavorId]); } // Xóa flavors không còn trong danh sách mới foreach ($flavorsToRemove as $flavorId) { $this->deleteProductFlavor($product, $flavorId); } // Cập nhật quantity cho flavors hiện tại (nếu có thay đổi) foreach ($newFlavorIds as $flavorId) { if (in_array($flavorId, $currentFlavorIds)) { $this->updateProductFlavorQuantity($product, $flavorId, $quantity[$flavorId]); } }
}

