public function updateProductFlavorQuantity(Product $product, $flavorId, $quantity)
{ // Lấy số lượng hiện tại của hương vị từ bảng pivot $currentQuantity = $product->flavors()->wherePivot('flavor_id', $flavorId)->first()->pivot->quantity; // Chỉ cập nhật nếu số lượng mới khác với số lượng hiện tại if ($currentQuantity != $quantity) { $product->flavors()->updateExistingPivot($flavorId, ['quantity' => $quantity]); }
}

