{ public function sendVerificationCode($email, $role) { $code = Str::random(10); $expiresAt = Carbon::now()->addMinutes(2); VerificationCode::create([ 'email' => $email, 'code' => $code, 'role' => $role, 'expires_at' => $expiresAt, ]); Mail::to($email)->send(new VerificationCodeMail($code)); } public function validateVerificationCode($email, $code, $role) { $verificationCode = VerificationCode::where('email', $email) ->where('code', $code) ->where('role', $role) ->where('expires_at', '>', Carbon::now()) ->first(); return $verificationCode !== null; } public function emailExists(string $email, string $role): bool { $table = $role === 'admin' ? 'admins' : 'users'; return DB::table($table)->where('email', $email)->exists(); }
} AuthenUserController : public function register(RegisterRequest $request)
{ $validatedData = $request->validated(); $isValid = $this->verificationService->validateVerificationCode($validatedData['email'], $validatedData['code'], $validatedData['role']); if ($isValid) { $user = new User([ 'name' => $validatedData['name'], 'email' => $validatedData['email'], 'password' => Hash::make($validatedData['password']), ]); $user->save(); return redirect()->route('login')->with('success', 'Đăng ký thành công. Hãy đăng nhập.'); } else { return back()->withErrors('Mã xác thực không đúng hoặc đã hết hạn.')->withInput(); }
} AuthenAdminController : public function sendVerificationCode(Request $request)
{ $request->validate([ 'role' => 'required|string', ]); $email = null; switch ($request->role) { case 'admin-reset-password': $request->validate([ 'email' => 'required|email', ]); if (!$this->verificationService->emailExists($request->email, 'admin')) { return response()->json(['errors' => ['email' => ['Email không tồn tại trong hệ thống.']]], 400); } $email = $request->email; break; case 'admin-change-password': $email = auth()->guard('admin')->user()->email; if (!$email) { return response()->json(['message' => 'Email không được tìm thấy cho tài khoản hiện tại.'], 400); } break; default: return response()->json(['message' => 'Role không hợp lệ.'], 400); } $this->verificationService->sendVerificationCode($email, $request->role); return response()->json(['message' => 'Mã xác thực đã được gửi.']);
} AdminController : public function resetPassword(ResetPasswordRequest $request)
{ if (!$this->verificationService->emailExists($request->email, 'admin')) { return back()->withErrors('Email không tồn tại trong hệ thống.')->withInput(); } $validatedData = $request->validated(); $isValid = $this->verificationService->validateVerificationCode($validatedData['email'], $validatedData['code'], $validatedData['role']); if ($isValid) { $admin = $this->adminService->getAdminByEmail($request->email); $result = $this->adminService->resetPassword($admin, $request->password); if ($result['status'] == 'error') { return back()->withErrors([$result['field'] => $result['message']]); } } else { return back()->withErrors('Mã xác thực không đúng hoặc đã hết hạn.')->withInput(); } return redirect()->route('admin.login')->with('success', 'Đã đổi mật khẩu thành công. Hãy đăng nhập');
} public function changePassword(ChangePasswordRequest $request)
{ $validatedData = $request->validated(); $admin = auth()->guard('admin')->user(); $isValid = $this->verificationService->validateVerificationCode($admin->email, $validatedData['code'], $validatedData['role']); if ($isValid) { $result = $this->adminService->changePassword($admin, $request->current_password, $request->new_password); if ($result['status'] == 'error') { return back()->withErrors([$result['field'] => $result['message']]); } } else { return back()->withErrors('Mã xác thực không đúng hoặc đã hết hạn.'); } return redirect()->back()->with('success', 'Đã đổi mật khẩu thành công.');
} UserController : public function changePassword(ChangePasswordRequest $request)
{ $validatedData = $request->validated(); $user = Auth::user(); $isValid = $this->verificationService->validateVerificationCode($user->email, $validatedData['code'], $validatedData['role']); if ($isValid) { $result = $this->userService->changePassword($request->user(), $request->current_password, $request->new_password); if ($result['status'] == 'error') { return back()->withErrors([$result['field'] => $result['message']]); } } else { return back()->withErrors('Mã xác thực không đúng hoặc đã hết hạn.'); } return redirect()->back()->with('success', 'Đã đổi mật khẩu thành công.');
} public function resetPassword(ResetPasswordRequest $request)
{ if (!$this->verificationService->emailExists($request->email, 'user')) { return back()->withErrors('Email không tồn tại trong hệ thống.'); } $validatedData = $request->validated(); $isValid = $this->verificationService->validateVerificationCode($validatedData['email'], $validatedData['code'], $validatedData['role']); if ($isValid) { $user = $this->userService->getUserByEmail($request->email); $result = $this->userService->resetPassword($user, $request->password); if ($result['status'] == 'error') { return back()->withErrors([$result['field'] => $result['message']]); } } else { return back()->withErrors('Mã xác thực không đúng hoặc đã hết hạn.'); } return redirect()->route('login')->with('success', 'Đã đổi mật khẩu thành công. Hãy đăng nhập');
}

