], 'google' => [ 'client_id' => env('GOOGLE_CLIENT_ID'), 'client_secret' => env('GOOGLE_CLIENT_SECRET'), 'redirect' => env('GOOGLE_REDIRECT_URL'),
], UserService public function findOrCreateUser($providerUser, $provider)
{ $authUser = User::where('email', $providerUser->getEmail())->first(); if ($authUser) { if (is_null($authUser->provider)) { throw ValidationException::withMessages([ 'email' => 'Email này đã tồn tại trong hệ thống và không thể đăng nhập bằng ' . $provider . '.', ]); } $authUser->update([ 'provider' => $provider, 'provider_id' => $providerUser->getId(), ]); return $authUser; } return User::create([ 'name' => $providerUser->name, 'email' => $providerUser->email, 'provider' => $provider, 'provider_id' => $providerUser->id, ]);
} AuthUserController public function redirectToFacebook()
{ return Socialite::driver('facebook')->redirect();
} public function handleFacebookCallback()
{ try { $user = Socialite::driver('facebook')->user(); $authUser = $this->userService->findOrCreateUser($user, 'facebook'); auth()->login($authUser, true); return redirect()->route('shop.index'); } catch (ValidationException $e) { return redirect()->route('login')->withErrors($e->errors()); }
} public function redirectToGoogle()
{ return Socialite::driver('google')->redirect();
} public function handleGoogleCallback()
{ try { $user = Socialite::driver('google')->user(); $authUser = $this->userService->findOrCreateUser($user, 'google'); auth()->login($authUser, true); return redirect()->route('shop.index'); } catch (ValidationException $e) { return redirect()->route('login')->withErrors($e->errors()); }
} Routes : // login facebook
