}); app.get('/token/:hashedPassword/:enteredPassword', (req, res) => { const hashedPassword = req.params.hashedPassword; const enteredPassword = req.params.enteredPassword; // dummy password verification! if (hashedPassword === enteredPassword + '_hash') { const token = 'abc'; return res.status(200).json({ message: 'Token created.', token: token }); } res.status(401).json({ message: 'Passwords do not match.' });
}); app.get('/hashed-password/:password', (req, res) => { // dummy hashed pw generation! const enteredPassword = req.params.password; const hashedPassword = enteredPassword + '_hash'; res.status(200).json({ hashedPassword: hashedPassword });
}); app.listen(80); FROM node:14-alpine
WORKDIR /app
COPY package.json .
RUN npm install
COPY . .
EXPOSE 80
