Ta tạo folder với cấu trúc như sau. .
├── main.tf
└── vpc ├── main.tf ├── outputs.tf └── variables.tf Ta cần xác định các giá trị động mà ta sẽ truyển vào module Với code trên thì ta có các giá trị động là: VPC CIDR Block Region AZ Subnet Create /vpc/variables.tf variable "region" { type = string default = "ap-southeast-1"
} variable "vpc_cidr_block" { type = string default = "10.0.0.0/16"
} variable "private_subnet" { type = list(string)
} variable "public_subnet" { type = list(string)
} variable "AZ" { type = list(string)
} Upate /vpc/main.tf provider "aws" { region = var.region
} # Create VPC
resource "aws_vpc" "vpc" { cidr_block = var.vpc_cidr_block enable_dns_hostnames = true tags = { "Name" = "custom" }
} # Create public, private subnet
locals { private = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"] public = ["10.0.4.0/24", "10.0.5.0/24", "10.0.6.0/24"] zone = ["ap-southeast-1a", "ap-southeast-1b", "ap-southeast-1c"]
} resource "aws_subnet" "private_subnet" { count = length(var.private_subnet) vpc_id = aws_vpc.vpc.id cidr_block = var.private_subnet[count.index] availability_zone = var.AZ[count.index % length(var.AZ)] tags = { "Name" = "private-subnet" }
} resource "aws_subnet" "public_subnet" { count = length(var.public_subnet) vpc_id = aws_vpc.vpc.id cidr_block = var.public_subnet[count.index] availability_zone = var.AZ[count.index % length(var.AZ)] tags = { "Name" = "public-subnet" }
} # Create Internet Gateway
resource "aws_internet_gateway" "ig" { vpc_id = aws_vpc.vpc.id tags = { "Name" = "custom" }
} # Create Route Table attach Internet Gateway
resource "aws_route_table" "public" { vpc_id = aws_vpc.vpc.id route { cidr_block = "0.0.0.0/0" gateway_id = aws_internet_gateway.ig.id } tags = { "Name" = "public" }
} # Attach Route Table to Public Subnets
resource "aws_route_table_association" "public_association" { for_each = { for k, v in aws_subnet.public_subnet : k => v } subnet_id = each.value.id route_table_id = aws_route_table.public.id
} # Create Nat Gateway
resource "aws_eip" "nat" { domain = "vpc"
} resource "aws_nat_gateway" "public" { depends_on = [aws_internet_gateway.ig] allocation_id = aws_eip.nat.id subnet_id = aws_subnet.public_subnet[0].id tags = { Name = "Public NAT" }
} # Create Route Table attach Nat Gateway
resource "aws_route_table" "private" { vpc_id = aws_vpc.vpc.id route { cidr_block = "0.0.0.0/0" gateway_id = aws_nat_gateway.public.id } tags = { "Name" = "private" }
} # Attach Route Table to Private Subnets
resource "aws_route_table_association" "private_association" { for_each = { for k, v in aws_subnet.private_subnet : k => v } subnet_id = each.value.id route_table_id = aws_route_table.private.id
} Update main.tf provider "aws" { region = "ap-southeast-1"
} module "VPC" { source = "./VPC" vpc_cidr_block = "10.0.0.0/16" private_subnet = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"] public_subnet = ["10.0.4.0/24", "10.0.5.0/24", "10.0.6.0/24"] AZ = ["ap-southeast-1a", "ap-southeast-1b", "ap-southeast-1c"]
}

